<?php
namespace Tests\Feature;
use App\Actions\ServiceOrders\{AssignTechnician,CancelServiceOrder,CreateServiceOrder,StartServiceOrder};use App\Enums\ServiceOrderType;use App\Filament\Resources\CustomerResource\Pages\{CreateCustomer,EditCustomer,ListCustomers};use App\Filament\Resources\ProductResource\Pages\ProductInventory;use App\Filament\Resources\ServiceOrderResource\Pages\{CreateServiceOrder as CreateServiceOrderPage,EditServiceOrder};use App\Filament\Resources\WaterPurifierResource\Pages\CreateWaterPurifier;use App\Models\{CustomerAddress,Product,PurifierBrand,PurifierModel,Technician,WaterPurifier};use Filament\Models\User as FilamentUser;use Illuminate\Foundation\Testing\DatabaseTransactions;use Illuminate\Support\Facades\Hash;use Livewire\Livewire;use Tests\TestCase;
class FilamentAdminCrmTest extends TestCase{use DatabaseTransactions;
private function admin(){return FilamentUser::create(['name'=>'Admin Test','email'=>uniqid().'@example.test','password'=>Hash::make('test-password'),'is_admin'=>true,'roles'=>[]]);}
public function test_guest_cannot_access_admin_and_admin_can_access_dashboard(){ $this->get('/admin')->assertRedirect();$this->actingAs($this->admin(),'filament')->get('/admin')->assertOk()->assertSeeText('Tổng khách hàng')->assertSeeText('Sản phẩm khách đang dùng')->assertSeeText('Đơn trong kỳ')->assertSeeText('Đơn đang thực hiện')->assertSeeText('Doanh thu trong kỳ')->assertSeeText('CRM')->assertSeeText('Dịch vụ')->assertSeeText('Nhân sự')->assertSeeText('Sản phẩm');}
public function test_dashboard_counts_orders_created_today_without_requiring_a_schedule(){ $widget=app(\App\Filament\Widgets\CrmDashboard::class);$widget->mount();$before=$widget->getDashboardData()['stats']['Đơn trong kỳ'];$p=WaterPurifier::factory()->create();$order=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);$data=$widget->getDashboardData();$this->assertSame($before+1,$data['stats']['Đơn trong kỳ']);$this->assertFalse($data['scheduled']->contains('id',$order->id));}
public function test_dashboard_can_filter_statistics_by_week_month_and_year(){ $widget=app(\App\Filament\Widgets\CrmDashboard::class);$widget->referenceDate='2026-08-25';foreach(['week','month','year'] as $period){$widget->period=$period;[$from,$to]=$widget->getPeriodRange();$this->assertTrue($from->lte(\Carbon\Carbon::parse('2026-08-25')));$this->assertTrue($to->gte(\Carbon\Carbon::parse('2026-08-25')));}}
public function test_customer_resource_can_query_without_n_plus_one_loop(){Livewire::actingAs($this->admin(),'filament')->test(ListCustomers::class)->assertStatus(200);}
public function test_admin_creates_customer_with_a_default_address(){Livewire::actingAs($this->admin(),'filament')->test(CreateCustomer::class)->set('record.full_name','Khách có địa chỉ')->set('record.phone','0909000000')->set('record.customer_type','individual')->set('record.initial_address','12 Nguyễn Huệ, Quận 1, TP.HCM')->set('record.status','active')->call('create')->assertHasNoErrors();$customer=\App\Models\Customer::where('phone','0909000000')->firstOrFail();$this->assertStringStartsWith('KH_',$customer->customer_code);$this->assertDatabaseHas('customer_addresses',['customer_id'=>$customer->id,'address_line'=>'12 Nguyễn Huệ, Quận 1, TP.HCM','is_default'=>1]);}
public function test_admin_sees_and_updates_customer_default_address_on_edit(){ $p=WaterPurifier::factory()->create();$address=CustomerAddress::create(['customer_id'=>$p->customer_id,'address_line'=>'Địa chỉ cũ','is_default'=>true]);Livewire::actingAs($this->admin(),'filament')->test(EditCustomer::class,['record'=>$p->customer_id])->assertSet('record.initial_address','Địa chỉ cũ')->set('record.initial_address','Địa chỉ mới đã sửa')->call('save')->assertHasNoErrors();$this->assertDatabaseHas('customer_addresses',['id'=>$address->id,'customer_id'=>$p->customer_id,'address_line'=>'Địa chỉ mới đã sửa','is_default'=>1]);$this->assertSame(1,CustomerAddress::where('customer_id',$p->customer_id)->count());}
public function test_all_admin_resource_pages_render(){ $this->actingAs($this->admin(),'filament');foreach(['customers','leads','marketing-sources','water-purifiers','service-orders','technicians','products','product-categories','purifier-brands','purifier-models'] as $slug){$this->get('/admin/resources/'.$slug)->assertOk();$this->get('/admin/resources/'.$slug.'/create')->assertOk();}}
public function test_customer_product_form_uses_generic_product_labels(){ $this->actingAs($this->admin(),'filament')->get('/admin/resources/water-purifiers/create')->assertOk()->assertSeeText('Khách hàng sở hữu')->assertSeeText('Sản phẩm khách hàng sử dụng')->assertSeeText('Serial / mã định danh')->assertSeeText('Ngày bàn giao / bắt đầu sử dụng')->assertSeeText('Tình trạng sử dụng');}
public function test_service_order_form_uses_customer_product_labels(){ $this->actingAs($this->admin(),'filament')->get('/admin/resources/service-orders/create')->assertOk()->assertSeeText('Khách hàng yêu cầu dịch vụ')->assertSeeText('Sản phẩm cần thực hiện dịch vụ')->assertSeeText('Loại dịch vụ')->assertSeeText('Thời gian hẹn thực hiện')->assertSeeText('Sản phẩm / dịch vụ phát sinh');}
public function test_admin_detail_pages_and_relation_managers_render(){ $this->actingAs($this->admin(),'filament');$purifier=WaterPurifier::factory()->create();$technician=Technician::factory()->create();$this->get('/admin/resources/customers/'.$purifier->customer_id.'/edit')->assertOk();$this->get('/admin/resources/water-purifiers/'.$purifier->id.'/edit')->assertOk();$this->get('/admin/resources/technicians/'.$technician->id.'/edit')->assertOk();}
public function test_water_purifier_histories_are_moved_to_a_separate_page(){ $this->actingAs($this->admin(),'filament');$product=Product::factory()->create(['product_type'=>'machine','name'=>'Máy lịch sử riêng']);$purifier=WaterPurifier::factory()->create(['product_id'=>$product->id]);$this->get('/admin/resources/water-purifiers')->assertOk()->assertSeeText('Xem lịch sử');$this->get('/admin/resources/water-purifiers/'.$purifier->id.'/edit')->assertOk()->assertSeeText('Xem lịch sử máy')->assertDontSeeText('Lịch sử thay lõi')->assertDontSeeText('Tên máy');$this->get('/admin/resources/water-purifiers/'.$purifier->id.'/history')->assertOk()->assertSeeText('Máy lịch sử riêng')->assertSeeText('Tình trạng lõi lọc')->assertSeeText('Lịch sử thay lõi')->assertSeeText('Lịch sử đơn dịch vụ');}
public function test_technician_assignments_are_moved_to_a_separate_history_page(){ $this->actingAs($this->admin(),'filament');$technician=Technician::factory()->create();$this->get('/admin/resources/technicians')->assertOk()->assertSeeText('Xem lịch sử');$this->get('/admin/resources/technicians/'.$technician->id.'/edit')->assertOk()->assertSeeText('Xem lịch sử kỹ thuật viên')->assertDontSeeText('Lịch sử phân công');$this->get('/admin/resources/technicians/'.$technician->id.'/history')->assertOk()->assertSeeText($technician->technician_code)->assertSeeText('Lịch sử phân công');}
public function test_admin_service_order_creation_uses_action_and_creates_history(){ $p=WaterPurifier::factory()->create();Livewire::actingAs($this->admin(),'filament')->test(CreateServiceOrderPage::class)->set('record.customer_id',$p->customer_id)->set('record.purifier_id',$p->id)->set('record.service_address','123 Đường Kiểm Thử, TP.HCM')->set('record.order_type',ServiceOrderType::MAINTENANCE)->set('record.shipping_fee',0)->set('record.discount_amount',0)->call('create');$this->assertDatabaseHas('service_orders',['customer_id'=>$p->customer_id,'service_address'=>'123 Đường Kiểm Thử, TP.HCM','status'=>'new']);$this->assertDatabaseHas('service_order_status_histories',['new_status'=>'new']);}
public function test_creating_service_order_with_product_calculates_total_immediately(){ $p=WaterPurifier::factory()->create();$product=Product::factory()->create(['name'=>'Máy tính tổng','selling_price'=>7550000,'cost_price'=>5000000]);Livewire::actingAs($this->admin(),'filament')->test(CreateServiceOrderPage::class)->set('record.customer_id',$p->customer_id)->set('record.purifier_id',$p->id)->set('record.service_address','Địa chỉ tính tổng')->set('record.order_type',ServiceOrderType::INSTALLATION)->set('record.shipping_fee',100000)->set('record.discount_amount',50000)->set('record.admin_item_product_id',$product->id)->assertSet('record.admin_item_unit_price','7550000.00')->set('record.admin_item_quantity',1)->call('create')->assertHasNoErrors();$order=\App\Models\ServiceOrder::latest('id')->first();$this->assertSame('7550000.00',$order->subtotal);$this->assertSame('7600000.00',$order->total_amount);$this->assertDatabaseHas('service_order_items',['service_order_id'=>$order->id,'product_id'=>$product->id,'quantity'=>1,'unit_price'=>7550000]);}
public function test_service_order_customer_prefills_default_address_but_allows_custom_address(){ $p=WaterPurifier::factory()->create();CustomerAddress::create(['customer_id'=>$p->customer_id,'address_line'=>'Địa chỉ phụ của khách','is_default'=>false]);CustomerAddress::create(['customer_id'=>$p->customer_id,'address_line'=>'Địa chỉ mặc định của khách','is_default'=>true]);Livewire::actingAs($this->admin(),'filament')->test(CreateServiceOrderPage::class)->set('record.customer_id',$p->customer_id)->assertSet('record.service_address','Địa chỉ mặc định của khách')->set('record.service_address','Địa chỉ làm dịch vụ tùy nhập')->assertSet('record.service_address','Địa chỉ làm dịch vụ tùy nhập');}
public function test_selecting_customer_prefills_default_address_but_address_remains_editable(){ $p=WaterPurifier::factory()->create();CustomerAddress::create(['customer_id'=>$p->customer_id,'address_line'=>'Địa chỉ phụ','is_default'=>false]);CustomerAddress::create(['customer_id'=>$p->customer_id,'address_line'=>'123 Địa chỉ mặc định','is_default'=>true]);Livewire::actingAs($this->admin(),'filament')->test(CreateWaterPurifier::class)->set('record.customer_id',$p->customer_id)->assertSet('record.installation_address','123 Địa chỉ mặc định')->set('record.installation_address','456 Địa chỉ nhập tay')->assertSet('record.installation_address','456 Địa chỉ nhập tay');}
public function test_water_purifier_selects_only_machine_products(){ $machine=Product::factory()->create(['product_type'=>'machine','name'=>'Máy được chọn']);$filter=Product::factory()->create(['product_type'=>'filter','name'=>'Lõi không được chọn']);$component=Livewire::actingAs($this->admin(),'filament')->test(CreateWaterPurifier::class);$field=collect($component->instance()->getForm()->getFlatSchema())->first(fn($field)=>method_exists($field,'getName')&&\Illuminate\Support\Str::endsWith($field->getName(),'product_id'));$this->assertArrayHasKey($machine->id,$field->getOptions());$this->assertArrayNotHasKey($filter->id,$field->getOptions());$component->set('record.product_id',$machine->id)->assertSet('record.product_id',$machine->id);}
public function test_admin_page_assigns_and_completes_through_actions(){ $this->assertSame('Sẵn sàng',\App\Filament\Resources\ServiceOrderResource::technicianStatusLabels()['available']);$p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);$t=Technician::factory()->create();$component=Livewire::actingAs($this->admin(),'filament')->test(EditServiceOrder::class,['record'=>$o->id])->set('record.admin_technician_id',$t->id)->call('assignTechnician')->assertSet('record.admin_technician_id',$t->id);$component->call('assignTechnician');$this->assertDatabaseHas('technician_assignments',['service_order_id'=>$o->id,'technician_id'=>$t->id,'status'=>'assigned']);$this->assertSame(1,$o->assignments()->count());app(StartServiceOrder::class)->execute($o->refresh(),$t);Livewire::actingAs($this->admin(),'filament')->test(EditServiceOrder::class,['record'=>$o->id])->call('completeOrder');$this->assertDatabaseHas('service_orders',['id'=>$o->id,'status'=>'completed']);}
public function test_edit_page_displays_the_latest_assigned_technician(){ $p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);$t=Technician::factory()->create(['working_status'=>'off']);$o->assignments()->create(['technician_id'=>$t->id,'status'=>'completed','assigned_at'=>now(),'completed_at'=>now()]);Livewire::actingAs($this->admin(),'filament')->test(EditServiceOrder::class,['record'=>$o->id])->assertSet('record.admin_technician_id',$t->id);}
public function test_service_order_list_keeps_technician_visible_after_completion(){ $p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);$t=Technician::factory()->create(['technician_code'=>'KTV-HOAN-THANH']);$o->assignments()->create(['technician_id'=>$t->id,'status'=>'completed','assigned_at'=>now(),'completed_at'=>now()]);$o->update(['status'=>'completed','completed_at'=>now()]);$loaded=\App\Filament\Resources\ServiceOrderResource\Pages\ListServiceOrders::getQuery()->findOrFail($o->id);$this->assertSame('KTV-HOAN-THANH',optional($loaded->assignments->first()->technician)->technician_code);}
public function test_completed_order_cannot_be_updated_from_edit_page(){ $p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);$o->update(['status'=>'completed','completed_at'=>now(),'internal_note'=>'Dữ liệu đã chốt']);$component=Livewire::actingAs($this->admin(),'filament')->test(EditServiceOrder::class,['record'=>$o->id]);$fields=$component->instance()->getForm()->getFlatSchema();$this->assertTrue(collect($fields)->every(fn($field)=>!method_exists($field,'isDisabled')||$field->isDisabled()));$this->expectException(\DomainException::class);$component->set('record.internal_note','Không được lưu')->call('save');}
public function test_cancelled_order_is_read_only(){ $p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);app(CancelServiceOrder::class)->execute($o);$component=Livewire::actingAs($this->admin(),'filament')->test(EditServiceOrder::class,['record'=>$o->id]);$fields=$component->instance()->getForm()->getFlatSchema();$this->assertTrue(collect($fields)->every(fn($field)=>!method_exists($field,'isDisabled')||$field->isDisabled()));$this->expectException(\DomainException::class);$component->call('save');}
public function test_admin_can_attach_technician_to_in_progress_order_without_regressing_status(){ $p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);$o->update(['status'=>'in_progress','started_at'=>now()]);$t=Technician::factory()->create();Livewire::actingAs($this->admin(),'filament')->test(EditServiceOrder::class,['record'=>$o->id])->set('record.admin_technician_id',$t->id)->call('assignTechnician')->assertSet('record.admin_technician_id',$t->id);$this->assertDatabaseHas('service_orders',['id'=>$o->id,'status'=>'in_progress']);$this->assertDatabaseHas('technician_assignments',['service_order_id'=>$o->id,'technician_id'=>$t->id,'status'=>'in_progress']);$this->assertDatabaseHas('technicians',['id'=>$t->id,'working_status'=>'busy']);}
public function test_admin_can_add_a_product_to_an_open_service_order(){ $p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);$product=Product::factory()->create(['name'=>'Lõi kiểm thử','sku'=>'TEST-FILTER','selling_price'=>150000,'cost_price'=>80000]);Livewire::actingAs($this->admin(),'filament')->test(EditServiceOrder::class,['record'=>$o->id])->set('record.admin_item_product_id',$product->id)->set('record.admin_item_type','product')->set('record.admin_item_quantity',2)->set('record.admin_item_discount',10000)->call('addItem')->assertHasNoErrors();$this->assertDatabaseHas('service_order_items',['service_order_id'=>$o->id,'product_id'=>$product->id,'name'=>'Lõi kiểm thử','quantity'=>2,'unit_price'=>150000]);}
public function test_saving_service_order_also_saves_entered_service_item(){ $p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);Livewire::actingAs($this->admin(),'filament')->test(EditServiceOrder::class,['record'=>$o->id])->set('record.admin_item_type','service')->set('record.admin_item_name','Vệ sinh máy')->set('record.admin_item_quantity',1)->set('record.admin_item_unit_price',120000)->call('save')->assertHasNoErrors()->assertRedirect(route('filament.resources.service-orders.edit',$o));$this->assertDatabaseHas('service_order_items',['service_order_id'=>$o->id,'product_id'=>null,'item_type'=>'service','name'=>'Vệ sinh máy','quantity'=>1,'unit_price'=>120000]);}
public function test_saving_service_order_without_item_input_does_not_create_an_item(){ $p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);Livewire::actingAs($this->admin(),'filament')->test(EditServiceOrder::class,['record'=>$o->id])->call('save')->assertHasNoErrors();$this->assertSame(0,$o->items()->count());}
public function test_saving_order_recalculates_total_after_shipping_and_order_discount_change(){ $p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);app(\App\Actions\ServiceOrders\AddServiceOrderItem::class)->execute($o,null,['item_type'=>'service','name'=>'Bảo dưỡng','quantity'=>2,'unit_price'=>100000,'discount_amount'=>10000]);Livewire::actingAs($this->admin(),'filament')->test(EditServiceOrder::class,['record'=>$o->id])->set('record.shipping_fee',30000)->set('record.discount_amount',20000)->call('save')->assertHasNoErrors();$this->assertDatabaseHas('service_orders',['id'=>$o->id,'subtotal'=>200000,'shipping_fee'=>30000,'discount_amount'=>20000,'total_amount'=>200000]);}
public function test_service_order_edit_page_displays_saved_items_section(){ $p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);app(\App\Actions\ServiceOrders\AddServiceOrderItem::class)->execute($o,null,['item_type'=>'service','name'=>'Dịch vụ cần hiển thị','quantity'=>1,'unit_price'=>90000]);$this->actingAs($this->admin(),'filament')->get('/admin/resources/service-orders/'.$o->id.'/edit')->assertOk()->assertSeeText('Sản phẩm / dịch vụ đã thêm')->assertSeeText('Dịch vụ cần hiển thị');}
public function test_selecting_product_prefills_selling_price_and_allows_price_override(){ $p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);$product=Product::factory()->create(['name'=>'Lõi tự điền giá','sku'=>'AUTO-PRICE','selling_price'=>175000,'cost_price'=>90000]);Livewire::actingAs($this->admin(),'filament')->test(EditServiceOrder::class,['record'=>$o->id])->set('record.admin_item_product_id',$product->id)->assertSet('record.admin_item_type','product')->assertSet('record.admin_item_name','Lõi tự điền giá')->assertSet('record.admin_item_unit_price','175000.00')->set('record.admin_item_unit_price',160000)->call('addItem')->assertHasNoErrors();$this->assertDatabaseHas('service_order_items',['service_order_id'=>$o->id,'product_id'=>$product->id,'unit_price'=>160000,'cost_price'=>90000]);}
public function test_admin_must_select_a_product_before_adding_a_product_item(){ $p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);Livewire::actingAs($this->admin(),'filament')->test(EditServiceOrder::class,['record'=>$o->id])->set('record.admin_item_type','product')->set('record.admin_item_product_id',null)->call('addItem')->assertHasErrors(['record.admin_item_product_id']);$this->assertSame(0,$o->items()->count());}
public function test_admin_cannot_complete_cancelled_order(){ $p=WaterPurifier::factory()->create();$o=app(CreateServiceOrder::class)->execute(['customer_id'=>$p->customer_id,'purifier_id'=>$p->id,'order_type'=>ServiceOrderType::MAINTENANCE]);app(CancelServiceOrder::class)->execute($o);Livewire::actingAs($this->admin(),'filament')->test(EditServiceOrder::class,['record'=>$o->id])->call('completeOrder')->assertHasErrors(['record.admin_item_product_id']);}
public function test_manual_stock_issue_shows_validation_error_instead_of_debug_page(){ $product=Product::factory()->create(['stock_quantity'=>1,'unit'=>'cái']);Livewire::actingAs($this->admin(),'filament')->test(ProductInventory::class,['record'=>$product->id])->set('movement_type','issue')->set('quantity',2)->call('adjustStock')->assertHasErrors(['quantity']);$this->assertSame('1.00',$product->refresh()->stock_quantity);}
}
